import java.util.Scanner;
public class Main {
    public static boolean isPerfect(int n) {
        if (n <= 1) {
            return false;
        }
        int sum = 0;
        for (int i = 1; i <= n / 2; i++) {
            if (n % i == 0) {
                sum += i;
            }
        }
        return sum == n;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        boolean result = isPerfect(n);
        if (result) {
            System.out.println(n + ":Yes");
        } else {
            System.out.println(n + ":No");
        }
        sc.close();
    }
}

import java.util.Scanner;
public class Main {
    public boolean inCircle(int x, int y, int r) {
        return x * x + y * y <= r * r;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int x = sc.nextInt();
        int y = sc.nextInt();
        int r = sc.nextInt();

        Main main = new Main();
        if (main.inCircle(x, y, r)) {
            System.out.println("yes");
        } else {
            System.out.println("no");
        }
        sc.close();
    }
}

import java.util.Scanner;
class Tool {
    public boolean isDaffodil(int num) {
        int a = num / 100;
        int b = num / 10 % 10;
        int c = num % 10;
        return a * a * a + b * b * b + c * c * c == num;
    }
}
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int num = sc.nextInt();
        Tool tool = new Tool();

        if (num < 100 || num > 999) {
            System.out.println("error");
        } else if (tool.isDaffodil(num)) {
            System.out.println("yes");
        } else {
            System.out.println("no");
        }

        for (int i = 100; i <= 999; i++) {
            if (tool.isDaffodil(i)) {
                System.out.println(i);
            }
        }
        sc.close();
    }
}

import java.util.Scanner;
class Tools {
    public int getAvg(int a, int b, int c) {
        return (a + b + c) / 3;
    }

    public void showAvg(int a, int b, int c) {
        System.out.println("Your average score=" + getAvg(a, b, c));
    }
}
